def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        current_time = op[1]

        # Remove expired entries
        expired_keys = []
        for key, (value, write_time) in cache.items():
            if write_time + ttl <= current_time:
                expired_keys.append(key)
        for key in expired_keys:
            del cache[key]

        if op[0] == 'put':
            key = op[2]
            value = op[3]

            # If key already exists, remove it first
            if key in cache:
                del cache[key]
            # If cache is at capacity, evict LRU
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Add the new entry
            cache[key] = (value, current_time)
            # Move to end (most recently used)
            cache.move_to_end(key)

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)

    return results

